mapper.update:
update qms_preship_tpl
   set tpl_nm = #{f.tplNm}, item_id = #{f.itemId}, item_class_id = #{f.itemClassId}, remark = #{f.remark}, use_yn = #{f.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tpl_id = #{id} and row_ver = #{f.rowVer}

update qms_preship_tpl_line
   set seq = #{l.seq}, grp_nm = #{l.grpNm}, check_text = #{l.checkText}, na_allowed_yn = #{l.naAllowedYn},
       photo_req_yn = #{l.photoReqYn}, use_yn = #{l.useYn}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tpl_line_id = #{l.tplLineId} and tpl_id = #{tplId}
   and (seq, grp_nm, check_text, na_allowed_yn, photo_req_yn, use_yn)
       is distinct from (#{l.seq}, #{l.grpNm}::varchar, #{l.checkText}::varchar, #{l.naAllowedYn}::char(1), #{l.photoReqYn}::char(1), #{l.useYn}::char(1))

update qms_preship_tpl_line
   set use_yn = 'N', row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tpl_id = #{tplId} and use_yn = 'Y'

   and tpl_line_id not in #{k}

