select  from qms_preship_insp h join wms_ship s on s.ship_id = h.ship_id
 where h.insp_id = #{inspId}
 for update of h

select  from qms_preship_insp h join wms_ship s on s.ship_id = h.ship_id
 where h.insp_id = #{inspId}
 for share of h

mapper.update:
update qms_preship_result
   set judge = #{judge}, remark = #{remark}, judged_at = now(), judged_by = #{by},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where result_id = #{resultId} and row_ver = #{rowVer}

update qms_preship_insp
   set inspector_nm = #{inspector}, witness_nm = #{witness}, remark = #{remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where insp_id = #{inspId} and row_ver = #{rowVer}

update qms_preship_insp
   set status = 'DONE', done_at = now(), done_by = #{by}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where insp_id = #{inspId} and status = 'OPEN'

update qms_preship_insp
   set status = 'OPEN', done_at = null, done_by = null, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where insp_id = #{inspId} and status = 'DONE'

update qms_preship_insp
   set status = 'CANCELLED', cancel_reason = #{reason}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where insp_id = #{inspId} and status = 'OPEN'

update qms_preship_punch
   set ncr_id = #{ncrId}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where punch_id = #{punchId} and row_ver = #{rowVer}

update qms_preship_result
   set judge = 'OK', judged_at = now(), judged_by = #{by}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where result_id = #{resultId} and row_ver = #{rowVer}
